<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3'
import { ref,onMounted,onUnmounted } from 'vue'
const props=defineProps<{result:{rooms?:any[];total_rooms?:number;next_batch?:string};filters:Record<string,any>;error:string|null;deleteStatus:any;deleteRoomID:string|null}>()
const search=ref(props.filters.search_term||''),order=ref(props.filters.order_by||'joined_members'),publicRooms=ref(props.filters.public_rooms??''),emptyRooms=ref(props.filters.empty_rooms??''),loading=ref(false)
const apply=()=>{loading.value=true;router.get('/rooms',{search_term:search.value,order_by:order.value,public_rooms:publicRooms.value||undefined,empty_rooms:emptyRooms.value||undefined,from:0,limit:50},{preserveState:true,onFinish:()=>loading.value=false})}
const page=(from:string|number)=>router.get('/rooms',{...props.filters,from,limit:50},{preserveState:true})
let deleteTimer:number|undefined
onMounted(()=>{if(props.deleteRoomID&&!['complete','failed'].includes(props.deleteStatus?.status)){deleteTimer=window.setInterval(()=>router.reload({only:['deleteStatus','deleteRoomID'],onSuccess:page=>{const status=(page.props as any).deleteStatus?.status;if((['complete','failed'].includes(status)||!(page.props as any).deleteRoomID)&&deleteTimer)window.clearInterval(deleteTimer)}}),3000)}})
onUnmounted(()=>{if(deleteTimer)window.clearInterval(deleteTimer)})
</script>
<template><Head title="مدیریت اتاق‌ها"/><v-container fluid class="pa-6"><div class="d-flex justify-space-between align-center mb-5"><h1 class="text-h4">اتاق‌ها</h1><v-btn color="primary" @click="apply">به‌روزرسانی</v-btn></div><v-card rounded="xl" class="pa-4"><v-alert v-if="deleteRoomID" :type="deleteStatus?.status==='failed'?'error':deleteStatus?.status==='complete'?'success':'info'" variant="tonal" class="mb-4">وضعیت حذف اتاق {{ deleteRoomID }}: {{ deleteStatus?.status||'در حال بررسی' }} {{ deleteStatus?.error||'' }}</v-alert><v-row><v-col cols="12" md="5"><v-text-field v-model="search" label="جستجوی نام، شناسه یا alias" prepend-inner-icon="mdi-magnify" hide-details @keyup.enter="apply"/></v-col><v-col cols="12" md="4"><v-select v-model="order" label="مرتب‌سازی" :items="[{title:'تعداد اعضا',value:'joined_members'},{title:'اندازه دیتابیس (۱۰ اتاق بزرگ)',value:'size'},{title:'نام',value:'name'}]" hide-details/></v-col><v-col cols="6" md="2"><v-select v-model="publicRooms" label="عمومی" :items="[{title:'همه',value:''},{title:'بله',value:'true'},{title:'خیر',value:'false'}]" hide-details/></v-col><v-col cols="6" md="2"><v-select v-model="emptyRooms" label="خالی" :items="[{title:'همه',value:''},{title:'فقط خالی',value:'true'},{title:'غیرخالی',value:'false'}]" hide-details/></v-col><v-col cols="12" md="2"><v-btn block color="primary" @click="apply">جستجو</v-btn></v-col></v-row><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-skeleton-loader v-if="loading" type="card@6"/><v-row v-else class="mt-2"><v-col v-for="room in (result.rooms||[])" :key="room.room_id" cols="12" md="6" lg="4"><v-card rounded="lg" variant="tonal" class="pa-3 h-100"><v-card-title class="text-subtitle-1">{{ room.name||'بدون نام' }}</v-card-title><v-card-subtitle>{{ room.room_id }}</v-card-subtitle><v-card-text><v-chip size="small">{{ room.joined_members??0 }} عضو</v-chip><div class="text-caption mt-2">اندازه دیتابیس: {{ room.estimated_size ? (room.estimated_size/1073741824).toFixed(2)+' GiB' : '—' }}</div></v-card-text><v-card-actions><v-btn variant="text" :href="'/rooms/'+encodeURIComponent(room.room_id)">جزئیات اتاق</v-btn></v-card-actions></v-card></v-col></v-row><v-divider class="my-4"/><div class="text-subtitle-1 mb-2">نمای جدولی اتاق‌ها</div><v-table density="comfortable"><thead><tr><th>نام</th><th>شناسه</th><th>اعضا</th><th>دسترسی</th><th>عملیات</th></tr></thead><tbody><tr v-for="room in (result.rooms||[])" :key="'table-'+room.room_id"><td>{{ room.name||'بدون نام' }}</td><td class="text-caption">{{ room.room_id }}</td><td>{{ room.joined_members??'—' }}</td><td>{{ room.estimated_size ? (room.estimated_size/1073741824).toFixed(2)+' GiB' : (room.public?'عمومی':'خصوصی') }}</td><td><v-btn size="small" variant="text" :href="'/rooms/'+encodeURIComponent(room.room_id)">جزئیات</v-btn></td></tr></tbody></v-table><div class="d-flex align-center justify-space-between mt-3"><span class="text-caption">تعداد اتاق‌ها: {{ result.total_rooms??0 }}</span><div class="d-flex ga-2"><v-btn variant="tonal" :disabled="Number(filters.from||0)<=0" @click="page(Math.max(0,Number(filters.from||0)-50))">قبلی</v-btn><v-btn variant="tonal" :disabled="!(result.next_batch||result.next_token)" @click="page(result.next_batch||result.next_token||0)">بعدی</v-btn></div></div></v-card></v-container></template>
